(window.webpackJsonp=window.webpackJsonp||[]).push([[119],{506:function(v,_,t){"use strict";t.r(_);var s=t(54),l=Object(s.a)({},(function(){var v=this,_=v.$createElement,t=v._self._c||_;return t("ContentSlotsDistributor",{attrs:{"slot-key":v.$parent.slotKey}},[t("h1",{attrs:{id:"入表实施路线"}},[t("a",{staticClass:"header-anchor",attrs:{href:"#入表实施路线"}},[v._v("#")]),v._v(" 入表实施路线")]),v._v(" "),t("p",[v._v("数据资产入表通过将企业的数据资源转化为数据资产，推动企业提升数据价值，入表是实现数据价值化的重要环节。数据资产被纳入财务报表，有利于优化资源配置，提高决策效率，以下是企业实现数据价值的几个阶段：")]),v._v(" "),t("p",[t("img",{attrs:{src:"https://s3.bmp.ovh/imgs/2024/10/04/23792ff9d6a5192b.jpg",alt:""}})]),v._v(" "),t("ul",[t("li",[v._v("在企业的生产信息化阶段，首要任务是进行全面的IT改造，旨在通过引入先进的信息系统，实现生产流程数字化和智能化。这个阶段企业信用建立有效的数据收集和存储机制，确保生产过程中产生的数据能够被准确记录并妥善保存，以完成原始数据的积累。")]),v._v(" "),t("li",[v._v("数据资源化阶段，完成信息化的企业通过数据采集、挖掘、清洗、标注、分析等步骤，形成可采可信的高质量数据资源，形成统一、标准化的数据集，从而构建数据资源并进行入表。")]),v._v(" "),t("li",[v._v("数据资产化阶段是将数据通过市场流通交易，为使用者或所有者带来经济利益的过程。在这一阶段，数据的确权是前提，需要明确数据的所有权、使用权和经营权，同时企业要对数据资产进行明确的价值定义，确保其经济价值的准确体现。")]),v._v(" "),t("li",[v._v("数据金融化阶段是实现数据价值的核心阶段，这标志着数据成为可以交换和流通的资本，其中可以推动数据和其他生产要素的深度融合，通过交换和流通实现数据价值的最大化。")])]),v._v(" "),t("h2",{attrs:{id:"三次入表理论"}},[t("a",{staticClass:"header-anchor",attrs:{href:"#三次入表理论"}},[v._v("#")]),v._v(" 三次入表理论")]),v._v(" "),t("p",[v._v("三次入表是指：以原始数据资源入表、以数据产品入表和相关资产入表。实际上这三次入表体现了企业对数据价值挖掘过程中，不同阶段、不同形态的数据资产入表，可以围绕这三次入表来规划和制定企业数据资源工作开展的全过程。")]),v._v(" "),t("p",[t("img",{attrs:{src:"https://s3.bmp.ovh/imgs/2024/10/04/646919e8d8045066.jpg",alt:""}})]),v._v(" "),t("p",[v._v("企业完成数据价值化的第一步是收集数据，其中重点工作是建立数据需求管理制度，确保数据需求能得到集中和系统的管理，从源头上保障原始数据的系统性、完整性和一致性。具体工作如下：")]),v._v(" "),t("ul",[t("li",[v._v("开展数据溯源：了解数据的来源，确保数据的权威性。")]),v._v(" "),t("li",[v._v("进行数据评估：对源头数据进行评估，包括异常值、不正确、不一致、缺失数据等情况的详细评估。")]),v._v(" "),t("li",[v._v("建立数据模型：结合数据类型、规模、时效性、应用场景等因素，设计数据存储、计算模型。")]),v._v(" "),t("li",[v._v("制定数据标准：建立统一的数据维度，对相关数据进行规范、标准化管理，确保数据质量。")]),v._v(" "),t("li",[v._v("数据接入和流转：对数据流转、存储、计算、展示等各个环节进行设计，形成数据接入及流传设计方案。")]),v._v(" "),t("li",[v._v("数据集成：将业务数据进行可视化表达，建立组织内各应用系统、各部门之间的集成共享机制，通过共享相关制度、标准、技术等方面的管理，促进组织内部数据互联互通。")])]),v._v(" "),t("p",[v._v("当企业数据资源进行过系统的盘点和梳理后，可以以成本法进行初始计量，并参考《暂行规定》的入表数据资源条件，将登记的数据权益作为数据资产入表的佐证材料，进行一次入表，具体步骤如下：")]),v._v(" "),t("ol",[t("li",[v._v("将数据从信息系统分离，并体现在会计报表--资产负债表--无形资产科目下。")]),v._v(" "),t("li",[v._v("将数据资源作为企业权益进行会计确认。")]),v._v(" "),t("li",[v._v("会计针对数据资源进行计量和记录。")])]),v._v(" "),t("p",[v._v("接下来企业可以分析目标客户或自身的数据需求和应用场景，选择一个试验性的目标，组织数据产品及其服务终端的开发。数据产品是指对数据资源投入的实际性加工或者创新性劳动，可满足内外部需求、提持续的、以数据为内容的服务形态。简化来说，数据产品=数据资源+数据算法模型+服务终端（APP、应用、API、SaaS等）。")]),v._v(" "),t("p",[v._v("数据产品实现其外部价值主要通过场内交易或场外交易两种模式。场内交易通常在专业的大数据交易平台上进行，这些平台为数据交易提供规范、透明和安全的环境，保障了交易的公正性和有效性。场外交易主要依赖买卖双方之间的直接协商和建立的信任关系，具有更高的灵活性和自主性。无论哪种交易，都要遵循相关的法律法规，确保数据交易的合法性和安全性。")]),v._v(" "),t("p",[v._v("“数据二十条”从国家层面推行了统一的数据要素市场运行体系，明确了三类场内交易市场的建设主体--国家交易所、地方数据交易中心和行业数据交易平台。它们与场外数据交易市场互联互通，为其提供交易场所和基础设施。企业选择合适的数据交易市场进行产品登记，并最终获得唯一标识符，数据产品标识符会记录每次链上的交易信息，并将电子订单、数字签名、发票等信息进行保存，这些凭证可以是数据资产二次入表的有利佐证。")]),v._v(" "),t("p",[v._v("数据资产凭证真实的记录了数据产品交易合同、交付情况以及结算情况，为数据资产确认为无形资产、存货，甚至单独的数据资产类别提供依据，为初始计量、后续计量的公允市场提供可靠依据。除了对外售卖和提供服务来赚取价值，还可以通过数据资产评估，参与数据出资入股、数据信贷等融资活动，实现其进入价值。")]),v._v(" "),t("p",[v._v("数据资产作为一项无形资产，不仅自身具备物权价值，还可以发挥担保物权的价值。具体而言，企业可以凭借这些数据资产对接银行，将其作为抵押物，从而获得金融机构的融资支持。当资产通过交换或其他途径转换成以货币计量的金融资产后，我们可以将其衍生资产进行第三次入表。")]),v._v(" "),t("h2",{attrs:{id:"入表的准备"}},[t("a",{staticClass:"header-anchor",attrs:{href:"#入表的准备"}},[v._v("#")]),v._v(" 入表的准备")]),v._v(" "),t("p",[v._v("入表的最终目的是与企业的使命和战略目标紧密结合，创造最大效益。这里的效益不仅仅是指经济效益，还包括创造就业机会、支持社区发展等社会效益。入表过程本身涵盖了多个不同的阶段，依托三次入表的理论，数据资源入表可以大致分为如下三个阶段：")]),v._v(" "),t("ul",[t("li",[v._v("一次入表：底层资产入表。初次入表主要是将企业实际形成的底层原始数据资源，按照《暂行规定》要求，首次纳入会计层面资产库。")]),v._v(" "),t("li",[v._v("二次入表：增值资产入表。在底层数据资源经过加工和应用后，必然会产生新的附加值，二次入表将这部分增值以货币的形式体现在财务报表中。")]),v._v(" "),t("li",[v._v("三次入表：金融资产转化入表。当数据资产通过交易或其他方式转化为以货币计量的金融资产后，将其纳入财务报表的过程几十第三次入表。")])]),v._v(" "),t("p",[t("img",{attrs:{src:"https://s3.bmp.ovh/imgs/2024/10/04/f5daafece05f477b.jpg",alt:""}})]),v._v(" "),t("p",[v._v("从数据价值构成层面，企业数据资产入表工作应紧密围绕以下三个核心方向展开：")]),v._v(" "),t("ol",[t("li",[t("strong",[v._v("证明企业内部数据资源的形成过程")]),v._v("。这一方向着重阐明企业如何逐步积累形成具有潜在经济价值的数据资源。这包括详细描述企业在构建和完善信息系统、深度处理数据以支撑业务需求过程中所进行的工作，以及数据资源的来源和处理过程，从而确立企业内部数据资源形成路径和价值基础。")]),v._v(" "),t("li",[t("strong",[v._v("证明存在数据内循环")]),v._v("。强调数据在企业内部的利用和流转情况，着重展示数据的实际应用，包括描述数据在企业内部如何被收集、存储、加工和利用，以及数据流向和应用场景。")]),v._v(" "),t("li",[t("strong",[v._v("证明数据内循环创造了价值")]),v._v("。这一方向更加强调数据所带来的具体经济效益或业务提升。除了描述数据流转外，还需要进一步量化贡献，例如推动企业的决策优化、提高生产效率、降低成本、改善营销策略等。证明这一点，企业需要提供数据内循环与业务成果之间的关联证据。")])]),v._v(" "),t("p",[v._v("能为企业带来经济利益是相关数据资源实现入表的重要前提，《暂行规定》中对如何证明数据资源为企业带来利益指出了答案：“企业应当按照企业会计准则相关规定，根据数据资源持有目的、形成方式、业务模式，以及与数据资源有关的经济利益的预期消耗方式等，对数据资源相关交易和事项进行会计确认、计量和报告。”简单来说就是通过“"),t("strong",[v._v("持有目的+形成方式+业务模式")]),v._v("”来完成对数据资源带来的利益进行分析证明。")]),v._v(" "),t("p",[v._v("例如，阿里巴巴持有大量用户行为数据，其持有目的是更好的理解用户需求，优化商品营销策略，从而提升营业额。在形成方式上，该企业对用户行为进行了深度挖掘和分析，形成了用户偏好画像和市场趋势预测等有价值的信息，在业务模式上，淘宝利用这些数据资源优化商品推荐算法，同时针对不同的用户群体推送定制化的营销策略，有效的提升了销售额。淘宝还通过直通车等形式，增加了大量的广告收入，这进一步挖掘了数据资源的商业价值。")]),v._v(" "),t("p",[v._v("此外，数据还可以实现二次价值。南方电网将其管理用户用电的信息系统中产生的数据提供给了金融机构，帮助金融机构通过分析对象企业的用电模式，反推对象企业的生产情况是否匹配在申请信贷时提交的材料。这个案例中，南方电网有效的实现了其内部管理系统产生数据的二次价值，实现了新的营收。通过这种形式可以一定程度上实现资产结构的优化。具体来说，在数据资产领域可以将信息化建设变为投资行为，由于信息化建设后数据和运维费用是持续产生的，将这部分费用资本化就意味着企业现金流不变的情况下增加了资产，降低了资产负债率。")])])}),[],!1,null,null,null);_.default=l.exports}}]);